const axios = require('axios');

module.exports = function (RED) {
    "use strict";

    function EventNode(n) {
        RED.nodes.createNode(this, n);
        let node = this;
        // 接收从前端传过来的 URL 参数
        this.event_type = n.event_type;
        this.on("input", function (msg, send, done) {
            msg = msg || {};
            msg.type = node.type;
            msg.event_type = node.event_type;
            send(msg);
            if (done) done();
        });
    }
    RED.nodes.registerType("Event", EventNode);

    RED.httpAdmin.post("/env-event/sync", function (req, res) {
        const { gridId, projectId, ip } = req.body;
        if (!gridId || !ip) {
            return res.status(400).json({ error: "缺少必要参数" });
        }
        const rawFlow = [];
        RED.nodes.eachNode(function (nodeData) {
            rawFlow.push(Object.assign({}, nodeData));
        });
        console.log(`>>> 检测到部署同步任务 | IP: ${ip} | GridId: ${gridId} | ProjectId: ${projectId}`);
        console.log(`>>> 节点数据: ${JSON.stringify(rawFlow)}`);
        const tabNode = rawFlow.find(n => n.type === "tab") || {};
        const requestBody = {
            projectId: projectId ? parseInt(projectId) : null,
            gridId: gridId,
            appName: tabNode.label || "未命名应用",
            description: tabNode.info || "",
            flowJson: JSON.stringify(rawFlow),
            ruleJson: ""
        };
        console.log(`>>> 请求体内容: ${JSON.stringify(requestBody)}`);
        axios.post(`http://${ip}:8080/api/taps/create`, requestBody, {
            headers: { 'Content-Type': 'application/json' },
            timeout: 120000
        })
        .then(() => {
            console.log(">>> 应用创建成功");
            res.json({ status: "success" });
        })
        .catch(err => {
            console.log(">>> 应用创建失败");
            res.status(500).json({ error: err.message });
        });
    });
};